/**
 * @claude-flow/testing - Agent Fixtures
 *
 * Comprehensive mock agents and agent configurations for testing V3 modules.
 * Supports all 15 V3 specialized swarm agents plus core development agents.
 *
 * Based on ADR-002 (Domain-Driven Design) and V3 agent specifications.
 */
import { vi, type Mock } from 'vitest';

/**
 * Agent types for V3 15-agent swarm
 */
export type V3AgentType =
  | 'queen-coordinator'
  | 'security-architect'
  | 'security-auditor'
  | 'memory-specialist'
  | 'swarm-specialist'
  | 'integration-architect'
  | 'performance-engineer'
  | 'core-architect'
  | 'test-architect'
  | 'project-coordinator'
  | 'coder'
  | 'reviewer'
  | 'tester'
  | 'planner'
  | 'researcher';

/**
 * Agent status type
 */
export type AgentStatus = 'idle' | 'busy' | 'terminated' | 'error' | 'starting';

/**
 * Agent configuration interface
 */
export interface AgentConfig {
  type: V3AgentType;
  name: string;
  capabilities: string[];
  priority?: number;
  metadata?: Record<string, unknown>;
  systemPrompt?: string;
  tools?: string[];
  maxConcurrentTasks?: number;
  timeout?: number;
}

/**
 * Agent instance interface
 */
export interface AgentInstance {
  id: string;
  type: V3AgentType;
  name: string;
  status: AgentStatus;
  capabilities: string[];
  createdAt: Date;
  lastActiveAt?: Date;
  currentTaskId?: string;
  metrics?: AgentMetrics;
}

/**
 * Agent metrics interface
 */
export interface AgentMetrics {
  tasksCompleted: number;
  tasksFailed: number;
  avgTaskDuration: number;
  totalDuration: number;
  errorRate: number;
  memoryUsageMb: number;
}

/**
 * Agent permissions interface
 */
export interface AgentPermissions {
  canSpawnAgents: boolean;
  canTerminateAgents: boolean;
  canAccessFiles: boolean;
  canExecuteCommands: boolean;
  canAccessNetwork: boolean;
  canAccessMemory: boolean;
  maxMemoryMb?: number;
  maxCpuPercent?: number;
  allowedPaths?: string[];
  blockedPaths?: string[];
}

/**
 * Agent spawn result interface
 */
export interface AgentSpawnResult {
  agent: AgentInstance;
  sessionId: string;
  startupTime: number;
  success: boolean;
  error?: Error;
}

/**
 * Agent termination result interface
 */
export interface AgentTerminationResult {
  agentId: string;
  success: boolean;
  duration: number;
  tasksTerminated: number;
  error?: Error;
}

/**
 * Agent health check result interface
 */
export interface AgentHealthCheckResult {
  agentId: string;
  status: AgentStatus;
  healthy: boolean;
  lastActivity: Date;
  metrics: AgentMetrics;
  issues?: string[];
}

