  | 'hierarchical'
  | 'mesh'
  | 'ring'
  | 'star'
  | 'adaptive'
  | 'hierarchical-mesh';

/**
 * Consensus protocol types
 */
export type ConsensusProtocol = 'raft' | 'pbft' | 'gossip' | 'crdt' | 'byzantine';

/**
 * Coordination status types
 */
export type CoordinationStatus =
  | 'initializing'
  | 'active'
  | 'coordinating'
  | 'consensus'
  | 'error'
  | 'shutdown';

/**
 * Swarm configuration interface
 */
export interface SwarmConfig {
  topology: SwarmTopology;
  maxAgents: number;
  name?: string;
  description?: string;
  coordination: CoordinationConfig;
  communication: CommunicationConfig;
  autoScale?: AutoScaleConfig;
  healthCheck?: HealthCheckConfig;
}

/**
 * Coordination configuration
 */
export interface CoordinationConfig {
  consensusProtocol: ConsensusProtocol;
  heartbeatInterval: number;
  electionTimeout: number;
  consensusRequired?: boolean;
  timeoutMs?: number;
  retryPolicy?: {
    maxRetries: number;
    backoffMs: number;
  };
}

/**
 * Communication configuration
 */
export interface CommunicationConfig {
  protocol: 'quic' | 'tcp' | 'websocket' | 'ipc';
  maxMessageSize: number;
  retryAttempts: number;
  compressionEnabled?: boolean;
  encryptionEnabled?: boolean;
}

/**
 * Auto-scale configuration
 */
export interface AutoScaleConfig {
  enabled: boolean;
  minAgents: number;
  maxAgents: number;
  scaleUpThreshold: number;
  scaleDownThreshold: number;
  cooldownMs?: number;
}

/**
 * Health check configuration
 */
export interface HealthCheckConfig {
  enabled: boolean;
  interval: number;
  timeout: number;
  unhealthyThreshold: number;
  healthyThreshold: number;
}

/**
 * Swarm state interface
 */
export interface SwarmState {
  id: string;
  topology: SwarmTopology;
  status: CoordinationStatus;
  agentCount: number;
  activeAgentCount: number;
  leaderId?: string;
  createdAt: Date;
  lastHeartbeat?: Date;
}

/**
 * Swarm message interface
 */
export interface SwarmMessage<T = unknown> {
  id: string;
  from: string;
  to: string | 'broadcast';
  type: 'task' | 'result' | 'status' | 'coordination' | 'heartbeat' | 'election';
  payload: T;
  timestamp: Date;
  correlationId?: string;
  replyTo?: string;
  ttl?: number;
  priority?: number;
}

/**
 * Swarm task interface
 */
export interface SwarmTask {
  id: string;
  name: string;
  type: string;
  payload: unknown;
  priority: number;
  assignedTo?: string;
  status: 'pending' | 'assigned' | 'running' | 'completed' | 'failed' | 'cancelled';
  dependencies?: string[];
  deadline?: Date;
  createdAt: Date;
  startedAt?: Date;
  completedAt?: Date;
}

/**
 * Swarm task result interface
 */
export interface SwarmTaskResult {
  taskId: string;
  agentId: string;
  success: boolean;
  output?: unknown;
  error?: Error;
  duration: number;
  metrics?: TaskMetrics;
}

/**
 * Task metrics interface
 */
export interface TaskMetrics {
  cpuTime: number;
  memoryUsage: number;
  ioOperations: number;
  networkCalls: number;
}

/**
 * Coordination result interface
 */
export interface CoordinationResult {
  success: boolean;
  completedTasks: number;
  failedTasks: number;
  totalDuration: number;
  agentMetrics: Map<string, AgentCoordinationMetrics>;
  consensusRounds?: number;
}

/**
 * Agent coordination metrics
 */
export interface AgentCoordinationMetrics {
  tasksCompleted: number;
  tasksFailed: number;
  averageTaskDuration: number;
  messagesProcessed: number;
  totalDuration: number;
}

/**
 * Consensus request interface
 */
export interface ConsensusRequest<T = unknown> {
  topic: string;
  options: T[];
  requiredVotes: number | 'majority' | 'all';
  timeout: number;
  voters?: string[];
}

/**
 * Consensus response interface
 */
export interface ConsensusResponse<T = unknown> {
  topic: string;
  decision: T | null;
  votes: Map<string, T>;
  consensus: boolean;
  votingDuration: number;
  participatingAgents: string[];
}

