/**
 * Create in-memory file system helper
 *
 * @example
 * const fs = createInMemoryFileSystemHelper();
 * await fs.createFile('/test.txt', 'content');
 * const content = await fs.readFile('/test.txt');
 */
export function createInMemoryFileSystemHelper(): FileSystemTestHelper {
  const files = new Map<string, string>();
  const tempDirs: string[] = [];

  return {
    async createTempDir(): Promise<string> {
      const dir = `/tmp/test-${Date.now()}-${Math.random().toString(36).slice(2)}`;
      tempDirs.push(dir);
      return dir;
    },

    async createFile(path: string, content: string): Promise<void> {
      files.set(path, content);
    },

    async readFile(path: string): Promise<string> {
      const content = files.get(path);
      if (content === undefined) {
        throw new Error(`File not found: ${path}`);
      }
      return content;
    },

    async cleanup(): Promise<void> {
      files.clear();
      tempDirs.length = 0;
    },
  };
}

/**
 * Performance test helper
 */
export interface PerformanceTestHelper {
  startMeasurement(name: string): void;
  endMeasurement(name: string): number;
  getMeasurements(): Record<string, number[]>;
  getStats(name: string): { min: number; max: number; avg: number; p95: number };
  clear(): void;
}

/**
 * Create performance test helper
 *
 * @example
 * const perf = createPerformanceTestHelper();
 * perf.startMeasurement('search');
 * await search();
 * const duration = perf.endMeasurement('search');
 */
export function createPerformanceTestHelper(): PerformanceTestHelper {
  const measurements = new Map<string, number[]>();
  const starts = new Map<string, number>();

  return {
    startMeasurement(name: string): void {
      starts.set(name, performance.now());
    },

    endMeasurement(name: string): number {
      const start = starts.get(name);
      if (start === undefined) {
        throw new Error(`No measurement started for: ${name}`);
      }

      const duration = performance.now() - start;
      starts.delete(name);

      if (!measurements.has(name)) {
        measurements.set(name, []);
      }
      measurements.get(name)!.push(duration);

      return duration;
    },

    getMeasurements(): Record<string, number[]> {
      return Object.fromEntries(measurements);
    },

    getStats(name: string): { min: number; max: number; avg: number; p95: number } {
      const values = measurements.get(name);
      if (!values || values.length === 0) {
        return { min: 0, max: 0, avg: 0, p95: 0 };
      }

      const sorted = [...values].sort((a, b) => a - b);
      const sum = sorted.reduce((a, b) => a + b, 0);

      return {
        min: sorted[0],
        max: sorted[sorted.length - 1],
        avg: sum / sorted.length,
        p95: sorted[Math.floor(sorted.length * 0.95)],
      };
    },

    clear(): void {
      measurements.clear();
      starts.clear();
    },
  };
}

/**
 * Standard V3 test setup
 *
 * @example
 * // In your test file:
 * setupV3Tests();
 *
 * describe('MyModule', () => {
 *   // tests...
 * });
 */
export function setupV3Tests(config: V3TestConfig = {}): void {
  configureTestEnvironment({
    resetMocks: true,
    suppressConsole: config.suppressConsole ?? false,
    env: {
      NODE_ENV: 'test',
      CLAUDE_FLOW_MODE: 'test',
      ...config.env,
    },
  });
}

/**
 * V3 test configuration
 */
export interface V3TestConfig {
  suppressConsole?: boolean | ('log' | 'warn' | 'error' | 'info')[];
  env?: Record<string, string>;
  timeout?: number;
}

/**
 * Wait for all pending promises to resolve
 *
 * @example
 * await flushPromises();
 */
export function flushPromises(): Promise<void> {
  return new Promise(resolve => setImmediate(resolve));
}

/**
 * Run with timeout
 *
 * @example
 * await withTimeout(async () => {
 *   await longRunningOperation();
 * }, 5000);
 */
export async function withTestTimeout<T>(
  fn: () => Promise<T>,
  timeoutMs: number = 5000
): Promise<T> {
  return Promise.race([
    fn(),
    new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error(`Test timed out after ${timeoutMs}ms`)), timeoutMs)
    ),
  ]);
}

/**
 * V3 Claude-Flow Swarm Test Instance
 *
 * Creates isolated swarm instances for testing
 * Supports 15-agent V3 swarm topology testing
 */
import { vi, type Mock } from 'vitest';
import { createMock, type MockedInterface, InteractionRecorder } from './create-mock.js';

/**
 * Agent types for V3 15-agent swarm
 */
export type V3AgentType =
  | 'queen-coordinator'
  | 'security-architect'
  | 'security-auditor'
  | 'memory-specialist'
  | 'swarm-specialist'
  | 'integration-architect'
  | 'performance-engineer'
  | 'core-architect'
  | 'test-architect'
  | 'project-coordinator'
  | 'coder'
  | 'reviewer'
  | 'tester'
  | 'planner'
  | 'researcher';

/**
 * Swarm topology types
 */
export type SwarmTopology = 'hierarchical' | 'mesh' | 'adaptive' | 'hierarchical-mesh';

/**
 * Agent interface for swarm testing
 */
export interface SwarmAgent {
  id: string;
  type: V3AgentType;
  status: 'idle' | 'busy' | 'terminated';
  capabilities: string[];
  execute(task: SwarmTask): Promise<SwarmTaskResult>;
  communicate(message: SwarmMessage): Promise<void>;
}

/**
 * Swarm message interface
 */
export interface SwarmMessage {
  from: string;
