  type: 'added' | 'removed' | 'changed' | 'deprecated';
  path: string;
  description: string;
  breaking: boolean;
  oldValue?: unknown;
  newValue?: unknown;
}

/**
 * Stored contracts
 */
interface StoredContracts {
  version: string;
  capturedAt: number;
  contracts: ContractDefinition[];
}

